import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DDY-poMm.js";const h=JSON.parse('{"title":"Users & KYC Review","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user-review.md","filePath":"guide/user-review.md","lastUpdated":1790683574000}'),i={name:"guide/user-review.md"};function r(o,e,l,c,d,u){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="users-kyc-review" tabindex="-1">Users &amp; KYC Review <a class="header-anchor" href="#users-kyc-review" aria-label="Permalink to &quot;Users &amp; KYC Review&quot;">​</a></h1><h2 id="user-management" tabindex="-1">User management <a class="header-anchor" href="#user-management" aria-label="Permalink to &quot;User management&quot;">​</a></h2><p>&quot;User Management&quot; in the admin console lets you view and manage all registered users:</p><ul><li>Basic profile: account, UID, registration time, inviter</li><li>Account status: normal / abnormal. Abnormal accounts see a clear notice on the user side</li><li>Credit score: the initial value for new users is set in &quot;Sign-up and login&quot; configuration</li><li>VIP tier: determined once a user&#39;s assets or activity reach the thresholds in &quot;VIP tiers&quot;</li></ul><h2 id="identity-verification-kyc" tabindex="-1">Identity verification (KYC) <a class="header-anchor" href="#identity-verification-kyc" aria-label="Permalink to &quot;Identity verification (KYC)&quot;">​</a></h2><p>The platform supports two levels, <strong>basic verification</strong> and <strong>advanced verification</strong>. Users submit documents on the user side, and the admin console reviews them.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User submits documents</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>A pending record appears in the admin &quot;KYC&quot; list</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Operator reviews documents → approve / reject</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Status updates on the user side</span></span></code></pre></div><h3 id="verification-and-withdrawal-limits" tabindex="-1">Verification and withdrawal limits <a class="header-anchor" href="#verification-and-withdrawal-limits" aria-label="Permalink to &quot;Verification and withdrawal limits&quot;">​</a></h3><p>The verification level is linked to <strong>withdrawal limits</strong>, set in the KYC limit configuration in the admin console. Users who have not reached the required level are restricted when withdrawing.</p><div class="tip custom-block"><p class="custom-block-title">Recommendation</p><p>When rejecting, give a clear reason — users see it. Vague rejection reasons turn straight into support tickets.</p></div><h2 id="bank-cards-payout-methods" tabindex="-1">Bank cards / payout methods <a class="header-anchor" href="#bank-cards-payout-methods" aria-label="Permalink to &quot;Bank cards / payout methods&quot;">​</a></h2><p>Payout methods submitted by users are also visible and manageable in the admin console.</p><div class="warning custom-block"><p class="custom-block-title">Privacy reminder</p><p>KYC documents and payout details are sensitive user information. We recommend:</p><ul><li>Granting KYC review menu permission only to roles that need it</li><li>Not exporting and saving them to personal devices</li><li>Using the built-in masking settings, which can be enabled per module under &quot;Basic Configuration → Data masking&quot;</li></ul></div><h2 id="geo-restrictions" tabindex="-1">Geo-restrictions <a class="header-anchor" href="#geo-restrictions" aria-label="Permalink to &quot;Geo-restrictions&quot;">​</a></h2><p>The platform can restrict access by region. When enabled, users in restricted regions see a region-blocked page when opening the user side.</p><h2 id="user-asset-lookup" tabindex="-1">User asset lookup <a class="header-anchor" href="#user-asset-lookup" aria-label="Permalink to &quot;User asset lookup&quot;">​</a></h2><p>The admin console can look up any user&#39;s assets and complete ledger. Every entry records the amount changed and the balance before and after, for reconciliation and complaint investigation.</p><div class="danger custom-block"><p class="custom-block-title">Manual balance adjustments</p><p>A manual adjustment directly changes a user&#39;s balance. It is fully recorded in the ledger but <strong>cannot be undone</strong> — a wrong adjustment can only be corrected by another adjustment in the opposite direction. Always double-check the UID, coin and amount before executing.</p></div>`,18)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
